export function createLearningUI({api,e,redraw,notify,modal,teacher}){
 let tasks=null,task=null,taskId='',submissions=[],loading=false;
 const error='<p class="error" role="alert"></p>';
 async function load(id=''){if(loading)return;loading=true;try{if(id){const data=await api('/assignments/'+id);task=data;taskId=id;if(teacher())submissions=(await api('/assignments/'+id+'/submissions')).submissions;}else tasks=(await api('/assignments')).assignments;}catch(er){notify(er.message);}finally{loading=false;redraw();}}
 function view(route){if(route==='tasks'&&!teacher()){if(tasks===null){load();return '<p role="status">Vazifalar yuklanmoqda…</p>';}return `<div class="page-heading"><div><span class="eyebrow">GURUH VAZIFALARI</span><h1>Topshiriqlar</h1><p>Ustozingiz bergan mashqlar va javoblaringiz.</p></div><button class="btn" data-learning-refresh>Yangilash</button></div><div class="assignment-list">${tasks.map(t=>`<a class="assignment-row" href="#assignment/${e(t.id)}"><div><small>${e(t.groupName)} · ${new Date(t.due).toLocaleString('uz-UZ')}</small><h3>${e(t.title)}</h3></div><span>${t.status==='graded'?t.score+'%':t.status==='pending'?'Tekshirilmoqda':t.due<Date.now()?'Muddat o‘tgan':'Boshlash →'}</span></a>`).join('')||'<section class="panel empty">Ustozingiz bergan vazifalar shu yerda chiqadi.</section>'}</div><a class="btn" href="#vocab">So‘zlarni takrorlash →</a>`;}
 if(!route.startsWith('assignment/'))return null;const id=route.slice(11);if(taskId!==id){load(id);return '<p role="status">Vazifa yuklanmoqda…</p>';}if(!task)return '';const {task:t,submission:s}=task;
 return `<a class="text-btn" href="#${teacher()?'groups':'tasks'}">← Orqaga</a><section class="studio-paper"><span class="eyebrow">VAZIFA · ${new Date(t.due).toLocaleString('uz-UZ')}</span><h1>${e(t.title)}</h1><p style="white-space:pre-wrap">${e(t.instructions)}</p>${s?`<div class="notice">${s.status==='graded'?'Baho: '+s.score+'%':'Ustoz tekshirishi kutilmoqda'}${s.feedback?'<p>'+e(s.feedback)+'</p>':''}</div>`:''}<form id="assignment-answer">${t.questions.map((q,i)=>`<fieldset><legend>${i+1}. ${e(q.prompt)}</legend>${q.type==='choice'?q.options.map((x,n)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${n}" required> ${e(x)}</label>`).join(''):`<textarea name="q${i}" rows="4" maxlength="5000" required aria-label="${i+1}-savol javobi"></textarea>`}</fieldset>`).join('')}${teacher()?'':error+'<button class="btn primary">Javobni yuborish</button>'}</form></section>${teacher()?`<section class="panel"><h2>O‘quvchi javoblari</h2>${submissions.map(s=>`<article class="assignment-review"><h3>${e(s.name)}</h3>${JSON.parse(s.answers).map((a,i)=>`<p><b>${i+1}.</b> ${e(t.questions[i].type==='choice'?t.questions[i].options[Number(a)]||a:a)}</p>`).join('')}<form data-mark-student="${e(s.student_id)}"><label>Baho (0–100)<input name="score" type="number" min="0" max="100" required value="${s.score??''}"></label><label>Izoh<textarea name="feedback" maxlength="2000">${e(s.feedback)}</textarea></label>${error}<button class="btn">Bahoni saqlash</button></form></article>`).join('')||'<p>Hali javob kelmagan.</p>'}</section>`:''}`;
 }
 function groupContent(tab,detail){
 if(tab==='policy'){const p=detail.policy;return `<section class="panel"><h2>Revision qoidalari</h2><form id="group-policy"><div class="form-grid">${[['dailyLimit','Kunlik so‘z limiti',1,500],['newLimit','Kunlik yangi so‘z',0,500],['deadlineHours','Yangi dars muddati (soat)',1,336]].map(([key,label,min,max])=>`<label>${label}<input type="number" name="${key}" min="${min}" max="${max}" value="${p[key]}" required></label>`).join('')}<label>Ketma-ket necha kun faoliyat bo‘lmasa ogohlantirish?<select name="inactiveDays">${[2,3,4,5,7].map(n=>`<option ${p.inactiveDays===n?'selected':''}>${n}</option>`).join('')}</select></label></div><p>Qiynalgan so‘zlar qisqa oraliqda, qolganlari uzoqroq oraliqda qaytadi. Ogohlantirish o‘quvchini avtomatik chetlatmaydi.</p>${error}<button class="btn primary">Saqlash</button></form></section>`;}
 if(tab==='redlist')return `<section class="panel"><h2>Redlist · e’tibor talab qilayotgan o‘quvchilar</h2><p>Revision bo‘lmagan har ${detail.policy.inactiveDays} kun — bitta ogohlantirish. Yangi dars ${detail.policy.deadlineHours} soatda kamida 80% bilan topshirilmasa — yana bitta omil. Har sabab alohida ko‘rsatiladi.</p>${detail.redlist.students.map(s=>`<article class="redlist-row"><b>${e(s.name)}</b><span class="tag ${s.warnings?'red':'green'}">${s.warnings} ogohlantirish</span><small>${s.frozen?"Tanaffus: "+new Date(s.control.freeze_until).toLocaleDateString("uz-UZ")+" gacha · ":""}${s.missedDays} kun revision yo‘q${s.overdue.length?' · Topshirilmagan: '+s.overdue.map(l=>e(l.title)).join(', '):''}</small><details class="personal-study"><summary>Shaxsiy revision rejasi</summary><form data-person-plan="${e(s.id)}"><div class="form-grid"><label>Tanaffus (kun)<input type="number" name="freezeDays" min="0" max="365" placeholder="Bo‘sh — o‘zgarmaydi; 0 — davom ettirish"></label><label>Qoldirilgan yangi so‘zlarni necha kunga yoyish?<input type="number" name="catchupDays" min="0" max="365" placeholder="Masalan, 30 yoki 60"></label><label>Shaxsiy kunlik limit<input type="number" name="dailyLimit" min="0" max="500" value="${s.control?.daily_limit??''}" placeholder="Bo‘sh — guruh limiti; 0 — pauza"></label></div><label><input type="checkbox" name="resetWarnings"> Oldingi ogohlantirishlarni bekor qilish</label><p class="help-text">Tanaffusda muddatlar suriladi va ogohlantirish hisoblanmaydi. Yoyish rejasi qoldirilgan so‘zlarni kichik testlarga ajratadi. 100 so‘z / 30 kun — kuniga 3–4 ta qo‘shimcha.</p>${error}<button class="btn primary">Rejani saqlash</button></form></details></article>`).join('')||'<p>Hali o‘quvchi yo‘q.</p>'}</section>`;
 if(tab==='assignments')return `<div class="section-heading"><h2>Guruh vazifalari</h2>${teacher()?'<button class="btn primary" data-new-assignment>＋ Vazifa yaratish</button>':''}</div><div class="assignment-list">${detail.assignments.map(t=>`<div class="assignment-row"><a href="#assignment/${e(t.id)}"><h3>${e(t.title)}</h3><small>${new Date(t.due).toLocaleString('uz-UZ')}</small></a>${teacher()?`<button class="btn" data-archive-task="${e(t.id)}">Arxivlash</button>`:'<a class="btn" href="#assignment/'+e(t.id)+'">Bajarish →</a>'}</div>`).join('')||'<section class="panel empty">Hali vazifa yo‘q.</section>'}</div>`;
 return '';
 }
 function newAssignment(){modal('Yangi vazifa',`<form id="new-assignment"><section class="assignment-import"><label>Fayldan vazifa tayyorlash<input id="assignment-source" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.docx"></label><select id="assignment-mode" aria-label="AI vazifa usuli"><option value="similar">Shunga o‘xshash yangi mashqlar</option><option value="original">Fayldagi mashqlar</option></select><button class="btn" type="button" id="assignment-ai">AI qoralama tayyorlash</button><p class="help-text">2 MB gacha. Fayl Cloudflare AI’da tahlil qilinadi. Savol va javoblarni tekshirib, keyin guruhga bering.</p><p id="assignment-ai-status" role="status"></p></section><label>Nomi<input name="title" maxlength="100" required placeholder="Grammar · Present Perfect"></label><label>Ko‘rsatma<textarea name="instructions" rows="3" maxlength="5000"></textarea></label><label>Muddat<input name="due" type="datetime-local" required></label><label>Savollar<textarea name="questions" rows="10" required placeholder="Test: She ___ here. | lives | live | living | *lives&#10;Matn: Describe your daily routine."></textarea></label><p class="help-text">Har qatorda bitta savol. Test: savol | variant 1 | variant 2 | *to‘g‘ri variant. Matn: ochiq savol. Matnli javobni o‘zingiz baholaysiz.</p>${error}<button class="btn primary">Guruhga berish</button></form>`);}
 function parseQuestions(raw){return raw.split(/\r?\n/).filter(l=>l.trim()).map(l=>{if(l.startsWith('Matn:'))return {type:'text',prompt:l.slice(5).trim()};const parts=l.replace(/^Test:\s*/,'').split('|').map(x=>x.trim()),prompt=parts.shift(),correctText=parts.pop();if(!correctText?.startsWith('*')||!parts.includes(correctText.slice(1)))throw Error('Test oxirida * belgisi bilan to‘g‘ri variantni qaytaring.');return {type:'choice',prompt,options:parts,correct:parts.indexOf(correctText.slice(1))};});}
 async function actionForm(form,fn){const b=form.querySelector('button');b.disabled=true;try{await fn();}catch(er){form.querySelector('.error').textContent=er.message;}finally{b.disabled=false;}}
 function mount(gid,reloadGroup){
 document.querySelectorAll('[data-person-plan]').forEach(form=>form.onsubmit=ev=>{ev.preventDefault();actionForm(form,async()=>{const d=Object.fromEntries(new FormData(form));await api('/groups/'+gid+'/student-plan',{studentId:form.dataset.personPlan,freezeDays:d.freezeDays===''?null:Number(d.freezeDays),catchupDays:d.catchupDays===''?null:Number(d.catchupDays),dailyLimit:d.dailyLimit===''?null:Number(d.dailyLimit),resetWarnings:!!d.resetWarnings});await reloadGroup(gid);notify('Shaxsiy revision rejasi saqlandi.');});});
 const policy=document.querySelector('#group-policy');if(policy)policy.onsubmit=ev=>{ev.preventDefault();actionForm(policy,async()=>{await api('/groups/'+gid+'/policy',Object.fromEntries([...new FormData(policy)].map(([k,v])=>[k,Number(v)])));await reloadGroup(gid);notify('Guruh qoidalari saqlandi.');});};
 const aiButton=document.querySelector('#assignment-ai');if(aiButton)aiButton.onclick=async()=>{const file=document.querySelector('#assignment-source').files[0],status=document.querySelector('#assignment-ai-status');if(!file){status.textContent='Faylni tanlang.';return;}if(file.size>2*1024*1024){status.textContent='Fayl 2 MB dan oshmasin.';return;}aiButton.disabled=true;status.textContent='Fayl tahlil qilinmoqda…';try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});const {draft}=await api('/groups/'+gid+'/assignment-draft',{file:{name:file.name,data},mode:document.querySelector('#assignment-mode').value});const form=document.querySelector('#new-assignment');form.elements.title.value=draft.title;form.elements.instructions.value=draft.instructions;form.elements.questions.value=draft.questions.map(q=>q.type==='text'?'Matn: '+q.prompt:'Test: '+q.prompt+' | '+q.options.join(' | ')+' | *'+q.options[q.correct]).join('\n');status.textContent='Qoralama tayyor. Savol va javoblarni tekshiring.';}catch(er){status.textContent=er.message;}finally{aiButton.disabled=false;}};const f=document.querySelector('#new-assignment');if(f)f.onsubmit=ev=>{ev.preventDefault();actionForm(f,async()=>{const data=Object.fromEntries(new FormData(f));await api('/groups/'+gid+'/assignments',{...data,due:new Date(data.due).getTime(),questions:parseQuestions(data.questions)});document.querySelector('#modal').close();await reloadGroup(gid);notify('Vazifa guruhga berildi. Botda /tasks orqali ham ochiladi.');});};
 const answer=document.querySelector('#assignment-answer');if(answer&&!teacher())answer.onsubmit=ev=>{ev.preventDefault();actionForm(answer,async()=>{const data=new FormData(answer);await api('/assignments/'+taskId+'/submit',{answers:task.task.questions.map((_,i)=>String(data.get('q'+i)||''))});await load(taskId);notify('Javob yuborildi.');});};
 document.querySelectorAll('[data-mark-student]').forEach(form=>form.onsubmit=ev=>{ev.preventDefault();actionForm(form,async()=>{const d=Object.fromEntries(new FormData(form));await api('/assignments/'+taskId+'/review',{...d,score:Number(d.score),studentId:form.dataset.markStudent});await load(taskId);notify('Baho saqlandi.');});});
 }
 document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.hasAttribute('data-new-assignment'))newAssignment();if(b.hasAttribute('data-learning-refresh')){tasks=null;load();}});
 return {view,groupContent,mount,reset(){tasks=null;task=null;taskId='';},parseQuestions};
}
